public sealed class DocumentaryMediaVerificationAdapterOptions { public const string SectionName="DocumentaryProductionAdapters:MediaVerification"; public bool Enabled {get;set;} public int DurationToleranceMilliseconds {get;set;}=500; public decimal FrameRateTolerance {get;set;}=.01m; public int ProbeTimeoutSeconds {get;set;}=60; public bool PersistVerificationDiagnostics {get;set;}=true; }

